@startuml

class Traveller {
  + Name : string
  + CompanyName : string
  + Address : string
  + BillingInformation : string
}

class TravelPreference {
  + Description : string
}

class SearchCriteria {
  + City : string
  + ArrivalDate : date
  + DepartureDate : date
  + RoomCount : int
  + RoomType : string
  + MinHotelRating : int
  + MaxCostPerNight : float
}

class PreliminaryBooking {
  + BookingIdentifier : string
  + Price : float
  + CityArea : string
  + HotelRating : int
}

class SpecialOffer {
  + Price : float
}

class Booking {
  + BookingIdentifier : string
  + IsPrepaid : boolean
  + IsConfirmed : boolean
  + CancellationDeadline : date
}

class Hotel {
  + Name : string
  + Address : string
  + Rating : int
}

class HotelChain {
  + Name : string
}

class RoomType {
  + Type : string
}

class City {
  + Name : string
}

class CreditCardInfo {
  + CardNumber : string
}

Traveller "1" -- "*" TravelPreference : has
Traveller "1" -- "*" Booking : makes
Traveller "1" -- "*" PreliminaryBooking : creates
Traveller "1" -- "1" CreditCardInfo : provides
Traveller "1" -- "0..*" SpecialOffer : receives

PreliminaryBooking "1" -- "*" SpecialOffer : generates
PreliminaryBooking "1" -- "0..1" Booking : converts to

Booking "1" -- "1" Hotel : confirmed by
Booking "1" -- "1" RoomType : involves

Hotel "1" -- "*" RoomType : offers
Hotel "1" -- "0..1" HotelChain : run by
Hotel "1" -- "1" City : located in
Hotel "1" -- "1" Address : at

City "1" -- "*" Hotel : contains

@enduml

